```name=frontend/src/App.tsx
import React, { useEffect, useState } from "react";

type Template = {
  id: number;
  createdAt: string;
  name?: string;
};

export default function App() {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [name, setName] = useState("");

  useEffect(() => {
    fetch("/api/health")
      .then((r) => r.json())
      .then(console.log)
      .catch(console.warn);

    fetch("/api/templates")
      .then((r) => r.json())
      .then((data) => setTemplates(data))
      .catch(() => setTemplates([]));
  }, []);

  async function create() {
    const res = await fetch("/api/templates", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name })
    });
    const t = await res.json();
    setTemplates((s) => [...s, t]);
    setName("");
  }

  return (
    <div style={{ padding: 20, fontFamily: "Arial, sans-serif" }}>
      <h1>POD Designer (Demo)</h1>
      <p>简单演示：保存模板到后端（后端以本地文件存储）</p>

      <div style={{ marginBottom: 12 }}>
        <input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="模板名称"
        />
        <button onClick={create} style={{ marginLeft: 8 }}>
          新建模板
        </button>
      </div>

      <h3>模板列表</h3>
      <ul>
        {templates.map((t) => (
          <li key={t.id}>
            {t.name ?? "(unnamed)"} — {new Date(t.createdAt).toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  );
}
```

```name=.github/workflows/ci.yml
name: CI Build and Push to GHCR

on:
  push:
    branches:
      - main

permissions:
  contents: read
  packages: write

jobs:
  build-and-push:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: 18

      - name: Login to GHCR
        uses: docker/login-action@v2
        with:
          registry: ghcr.io
          username: ${{ github.actor }}
          password: ${{ secrets.GITHUB_TOKEN }}

      - name: Build & push backend image
        uses: docker/build-push-action@v4
        with:
          context: ./backend
          push: true
          tags: ghcr.io/${{ github.repository_owner }}/pod-designer-backend:latest

      - name: Build & push frontend image
        uses: docker/build-push-action@v4
        with:
          context: ./frontend
          push: true
          tags: ghcr.io/${{ github.repository_owner }}/pod-designer-frontend:latest
```

说明与注意事项（简要）
- 本地 docker-compose 会把 backend 的 data 目录挂载到 ./backend/data；因此模板会保存在本地仓库目录下（方便调试）。
- CI 使用 `secrets.GITHUB_TOKEN` 登录 GHCR，workflow 已配置 permissions: packages: write。请确保仓库 Actions 权限允许写入 packages（设置：Repository → Settings → Actions → General → Workflow permissions → Enable read and write）。
- 如果想在 GHCR 使用组织名或不同 image 名称，可以在 workflow 中调整 tags。
- 如果你需要把镜像自动部署到远程服务器或 k8s，我可以在此基础上添加 deploy 步骤（SSH 或 kubectl/helm）。

