2) backend/src/s3.ts（增加 ensureBucket 创建 bucket 的实现）
```ts
import { S3Client, PutObjectCommand, GetObjectCommand, CreateBucketCommand, HeadBucketCommand } from "@aws-sdk/client-s3";
import stream from "stream";

const REGION = process.env.S3_REGION || "us-east-1";
const ENDPOINT = process.env.S3_ENDPOINT; // eg http://minio:9000
const ACCESS_KEY = process.env.S3_ACCESS_KEY || "minioadmin";
const SECRET_KEY = process.env.S3_SECRET_KEY || "minioadmin";
const BUCKET = process.env.S3_BUCKET || "pod";

const client = new S3Client({
  region: REGION,
  endpoint: ENDPOINT,
  credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY },
  forcePathStyle: true
});

export async function ensureBucket() {
  try {
    // Check if bucket exists
    await client.send(new HeadBucketCommand({ Bucket: BUCKET }));
    return BUCKET;
  } catch (err) {
    // Try to create (MinIO supports CreateBucket)
    try {
      await client.send(new CreateBucketCommand({ Bucket: BUCKET }));
      return BUCKET;
    } catch (createErr) {
      console.warn("ensureBucket: could not create bucket:", createErr);
      throw createErr;
    }
  }
}

export async function uploadObject(key: string, buffer: Buffer, contentType = "application/octet-stream") {
  await client.send(new PutObjectCommand({
    Bucket: BUCKET,
    Key: key,
    Body: buffer,
    ContentType: contentType
  }));
  // Build and return accessible URL (use S3_ENDPOINT if provided)
  const endpoint = ENDPOINT ? ENDPOINT.replace(/\/+$/, "") : "";
  const url = endpoint ? `${endpoint}/${BUCKET}/${key}` : `${BUCKET}/${key}`;
  return url;
}

export async function getObjectStream(key: string) {
  const out = await client.send(new GetObjectCommand({ Bucket: BUCKET, Key: key }));
  return out.Body as stream.Readable;
}
```

3) backend/src/routes/uploads.ts（新增把 job 推送到队列，同时在 GET /jobs/:id 返回完整 URL）
```ts
import express from "express";
import multer from "multer";
import { uploadObject, ensureBucket } from "../s3";
import pool from "../db";
import { Queue } from "bullmq";

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 30 * 1024 * 1024 } });

const redisConnection = {
  host: process.env.REDIS_HOST || "localhost",
  port: Number(process.env.REDIS_PORT || 6379)
};
const queue = new Queue("image-processing", { connection: redisConnection });

router.post("/", upload.single("file"), async (req, res) => {
  try {
    if (!req.file) return res.status(400).json({ error: "no file" });

    // ensure bucket exists (best-effort)
    await ensureBucket();

    const key = `uploads/${Date.now()}-${req.file.originalname}`;
    const url = await uploadObject(key, req.file.buffer, req.file.mimetype);
    res.json({ url, key });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: "upload failed" });
  }
});

router.post("/process", express.json(), async (req, res) => {
  const { key, actions } = req.body;
  if (!key) return res.status(400).json({ error: "missing key" });

  // create DB job record first
  const r = await pool.query(
    `INSERT INTO jobs (type, payload, status) VALUES ($1,$2,$3) RETURNING id`,
    ["process_image", { key, actions: actions || [] }, "queued"]
  );
  const jobId = r.rows[0].id;

  // enqueue a job into BullMQ so worker will pick it up
  await queue.add("process", { jobId, payload: { key, actions: actions || [] } });

  res.status(201).json({ jobId });
});

router.get("/jobs/:id", async (req, res) => {
  const id = req.params.id;
  const result = await pool.query(`SELECT * FROM jobs WHERE id = $1`, [id]);
  if (result.rowCount === 0) return res.status(404).json({ error: "not found" });
  const job = result.rows[0];

  // if job.result.key exists, expose a full URL using S3_ENDPOINT and BUCKET env
  let resultUrl = undefined;
  try {
    const endpoint = process.env.S3_ENDPOINT ? process.env.S3_ENDPOINT.replace(/\/+$/, "") : "";
    const bucket = process.env.S3_BUCKET || "pod";
    if (job.result && job.result.key) {
      resultUrl = endpoint ? `${endpoint}/${bucket}/${job.result.key}` : `${bucket}/${job.result.key}`;
    }
  } catch (err) {
    // ignore
  }

  res.json({ ...job, result: { ...(job.result || {}), url: resultUrl } });
});

export default router;
```

