5) frontend/src/components/Editor.tsx（上传后轮询 job 状态并自动显示 processed 图像）
```tsx
import React, { useRef, useState } from "react";
import { Stage, Layer, Image as KImage, Text, Rect } from "react-konva";

function useImage(url?: string) {
  const [img, setImg] = useState<HTMLImageElement | null>(null);
  React.useEffect(() => {
    if (!url) return;
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => setImg(image);
    image.src = url;
    return () => { setImg(null); };
  }, [url]);
  return img;
}

export default function Editor({ onSave }: { onSave: (t: any) => void }) {
  const [uploading, setUploading] = useState(false);
  const [imageUrl, setImageUrl] = useState<string | undefined>();
  const [processedUrl, setProcessedUrl] = useState<string | undefined>();
  const [name, setName] = useState("");
  const img = useImage(processedUrl || imageUrl);
  const stageRef = useRef<any>(null);

  async function pollJob(jobId: number) {
    const maxAttempts = 60; // e.g., 60 * 1s = 1 minute
    let attempts = 0;
    return new Promise<string | null>((resolve) => {
      const iv = setInterval(async () => {
        attempts++;
        try {
          const r = await fetch(`/api/uploads/jobs/${jobId}`);
          if (!r.ok) {
            if (attempts >= maxAttempts) {
              clearInterval(iv);
              resolve(null);
            }
            return;
          }
          const j = await r.json();
          if (j.status === "done" && j.result && j.result.url) {
            clearInterval(iv);
            resolve(j.result.url);
            return;
          }
          if (j.status === "failed") {
            clearInterval(iv);
            resolve(null);
            return;
          }
          if (attempts >= maxAttempts) {
            clearInterval(iv);
            resolve(null);
          }
        } catch (err) {
          // ignore and retry
          if (attempts >= maxAttempts) {
            clearInterval(iv);
            resolve(null);
          }
        }
      }, 1000);
    });
  }

  async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0];
    if (!f) return;
    setUploading(true);
    setProcessedUrl(undefined);
    const fd = new FormData();
    fd.append("file", f);
    const res = await fetch("/api/uploads", { method: "POST", body: fd });
    const data = await res.json();
    setImageUrl(data.url);

    // create process job
    const procRes = await fetch("/api/uploads/process", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ key: data.key, actions: ["resize"] })
    });
    const proc = await procRes.json();
    if (proc.jobId) {
      const url = await pollJob(proc.jobId);
      if (url) {
        setProcessedUrl(url);
      } else {
        console.warn("Processing failed or timed out");
      }
    }
    setUploading(false);
  }

  async function saveTemplate() {
    const stage = stageRef.current;
    const json = stage.toJSON();
    const res = await fetch("/api/templates", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: name || "untitled", design: json, assets: processedUrl ? [processedUrl] : imageUrl ? [imageUrl] : [] })
    });
    const r = await res.json();
    onSave({ id: r.id, name: name || "untitled", created_at: r.created_at });
    setName("");
  }

  return (
    <div>
      <div style={{ marginBottom: 12 }}>
        <input type="file" accept="image/*" onChange={handleFile} />
        <input placeholder="模板名称" value={name} onChange={(e) => setName(e.target.value)} style={{ marginLeft: 8 }} />
        <button onClick={saveTemplate} style={{ marginLeft: 8 }}>保存模板</button>
        {uploading && <span style={{ marginLeft: 8 }}>上传/处理中…</span>}
      </div>

      <div style={{ border: "1px solid #ccc", width: 800, height: 600 }}>
        <Stage width={800} height={600} ref={stageRef}>
          <Layer>
            <Rect x={0} y={0} width={800} height={600} fill="#fff" />
            {img && <KImage image={img} x={50} y={50} width={700} height={500} />}
            <Text text="示例文本" x={60} y={60} fontSize={20} />
          </Layer>
        </Stage>
      </div>
    </div>
  );
}
```

