2) EXIF 工具：解析并抽取 GPS/orientation（exifr）
```ts name=frontend/src/utils/exif.ts
import * as exifr from "exifr";

export type ExifInfo = {
  latitude?: number;
  longitude?: number;
  orientation?: number | null;
  make?: string | null;
  model?: string | null;
  [k: string]: any;
};

export async function parseExif(blob: Blob): Promise<ExifInfo | null> {
  try {
    const data = await exifr.parse(blob, { gps: true });
    if (!data) return null;
    const lat = (data as any).latitude ?? (data as any).gps?.latitude;
    const lon = (data as any).longitude ?? (data as any).gps?.longitude;
    const orientation = (data as any).Orientation ?? (data as any).orientation;
    const make = (data as any).Make ?? null;
    const model = (data as any).Model ?? null;
    return { latitude: lat, longitude: lon, orientation, make, model, raw: data };
  } catch (err) {
    console.warn("exif parse failed", err);
    return null;
  }
}
```

3) Mask 编辑器（Konva）—— 画笔 / 橡皮 / 撤销 / 保存 mask
```tsx name=frontend/src/components/MaskEditor.tsx
import React, { useRef, useState } from "react";
import { Stage, Layer, Line, Image as KImage } from "react-konva";

type Props = {
  width?: number;
  height?: number;
  imageSrc?: string; // background image to show under mask
  initialStrokes?: Array<number[]>; // optional initial strokes (array of points arrays)
  onExportMask?: (dataUrl: string) => void;
};

export default function MaskEditor({ width = 800, height = 600, imageSrc, initialStrokes = [], onExportMask }: Props) {
  const [tool, setTool] = useState<"brush" | "eraser">("brush");
  const [brushSize, setBrushSize] = useState(20);
  const [strokes, setStrokes] = useState<Array<{ points: number[]; color: string; size: number }>>(
    initialStrokes.length ? initialStrokes.map((pts) => ({ points: pts, color: "black", size: brushSize })) : []
  );
  const isDrawingRef = useRef(false);
  const stageRef = useRef<any>(null);

  // load image for background preview
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);
  React.useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => setImageObj(img);
    img.src = imageSrc;
    return () => { setImageObj(null); };
  }, [imageSrc]);

  function handleMouseDown(e: any) {
    isDrawingRef.current = true;
    const pos = e.target.getStage().getPointerPosition();
    if (!pos) return;
    const newStroke = { points: [pos.x, pos.y], color: tool === "brush" ? "black" : "rgba(0,0,0,1)", size: brushSize };
    setStrokes((s) => [...s, newStroke]);
  }

  function handleMouseMove(e: any) {
    if (!isDrawingRef.current) return;
    const pos = e.target.getStage().getPointerPosition();
    if (!pos) return;
    setStrokes((s) => {
      const copy = s.slice();
      const last = copy[copy.length - 1];
      last.points = last.points.concat([pos.x, pos.y]);
      return copy;
    });
  }

  function handleMouseUp() {
    isDrawingRef.current = false;
  }

  function undo() {
    setStrokes((s) => s.slice(0, -1));
  }

  function clear() {
    setStrokes([]);
  }

  function exportMask() {
    if (!stageRef.current) return;
    const stage = stageRef.current;
    // create a new stage sized same, but render only mask layer as binary mask: black = mask, white = background
    const dataUrl = stage.toDataURL({ pixelRatio: 1, mimeType: "image/png" });
    onExportMask?.(dataUrl);
  }

  return (
    <div>
      <div style={{ marginBottom: 8, display: "flex", gap: 8, alignItems: "center" }}>
        <label>
          工具:
          <select value={tool} onChange={(e) => setTool(e.target.value as any)} style={{ marginLeft: 6 }}>
            <option value="brush">画笔（添加）</option>
            <option value="eraser">橡皮（擦除）</option>
          </select>
        </label>
        <label style={{ marginLeft: 12 }}>
          笔刷大小:
          <input type="range" min={4} max={80} value={brushSize} onChange={(e) => setBrushSize(Number(e.target.value))} style={{ marginLeft: 6 }} />
          <span style={{ marginLeft: 6 }}>{brushSize}px</span>
        </label>
        <button onClick={undo}>撤销</button>
        <button onClick={clear}>清空</button>
        <button onClick={exportMask} style={{ marginLeft: "auto", background: "#0b79f7", color: "#fff" }}>保存掩码</button>
      </div>

      <div style={{ border: "1px solid #ccc", width, height }}>
        <Stage
          width={width}
          height={height}
          ref={stageRef}
          onMouseDown={handleMouseDown}
          onMousemove={handleMouseMove}
          onMouseup={handleMouseUp}
          onTouchStart={handleMouseDown}
          onTouchMove={handleMouseMove}
          onTouchEnd={handleMouseUp}
        >
          <Layer>
            {imageObj && <KImage image={imageObj} x={0} y={0} width={width} height={height} />}
            {/* render strokes as black lines (mask) */}
            {strokes.map((s, i) => (
              <Line
                key={i}
                points={s.points}
                tension={0.2}
                stroke={tool === "eraser" ? "white" : "black"}
                strokeWidth={s.size}
                lineCap="round"
                lineJoin="round"
                globalCompositeOperation={tool === "eraser" ? "destination-out" : "source-over"}
              />
            ))}
          </Layer>
        </Stage>
      </div>
    </div>
  );
}
```

4) 更新 CaptureGuide：加入 EXIF 解析、自动质量门控（重拍/强制使用）、上传时携带 metadata（EXIF），并在完成后触发 onComplete（包含 exif）
```tsx name=frontend/src/components/CaptureGuide.tsx
import React, { useEffect, useRef, useState } from "react";
import useCamera from "../hooks/useCamera";
import { analyzeImageBlob, ImageQuality } from "../utils/imageQuality";
import { parseExif, ExifInfo } from "../utils/exif";

type ViewKey = "front" | "rear" | "left" | "right" | string;

export type CaptureResult = {
  view: ViewKey;
  file?: File;
  blobUrl?: string;
  upload?: { url: string; key: string } | null;
  quality?: ImageQuality;
  exif?: ExifInfo | null;
  flagged?: boolean; // flagged if auto gate triggered (user forced)
};

type Props = {
  views?: ViewKey[]; // default ['front','rear','left','right']
  onComplete?: (results: CaptureResult[]) => void;
  autoUpload?: boolean;
};

export default function CaptureGuide({ views = ["front", "rear", "left", "right"], onComplete, autoUpload = true }: Props) {
  const [index, setIndex] = useState(0);
  const currentView = views[index];
  const [results, setResults] = useState<CaptureResult[]>([]);
  const [busy, setBusy] = useState(false);
  const [warning, setWarning] = useState<string | null>(null);
  const [gateLocked, setGateLocked] = useState(false); // when gate suggests retake

  const { stream, start, stop, facingMode, toggleFacing } = useCamera();
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    start().catch(() => {});
    return () => stop();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(() => {});
    }
  }, [stream]);

  async function handleCaptureFromCamera() {
    setBusy(true);
    setWarning(null);
    try {
      const video = videoRef.current;
      if (!video) throw new Error("Camera not ready");
      let canvas = canvasRef.current;
      if (!canvas) {
        canvas = document.createElement("canvas");
        canvasRef.current = canvas;
      }
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");
      if (!ctx) throw new Error("Canvas not supported");
      ctx.drawImage(video, 0, 0, w, h);
      const blob = await new Promise<Blob | null>((resolve) => canvas!.toBlob((b) => resolve(b), "image/jpeg", 0.95));
      if (!blob) throw new Error("Failed to capture image");
      await handleCapturedBlob(blob);
    } catch (err: any) {
      console.error("capture error", err);
      setWarning("拍照失败，请重试或使用文件选择上传。");
    } finally {
      setBusy(false);
    }
  }

  async function handleFileInput(ev: React.ChangeEvent<HTMLInputElement>) {
    const f = ev.target.files?.[0];
    if (!f) return;
    setBusy(true);
    setWarning(null);
    try {
      await handleCapturedBlob(f);
    } finally {
      setBusy(false);
    }
  }

  async function handleCapturedBlob(blobOrFile: Blob | File) {
    const file = blobOrFile instanceof File ? blobOrFile : new File([blobOrFile], `${currentView}-${Date.now()}.jpg`, { type: "image/jpeg" });
    // parse exif
    const exif = await parseExif(file);
    // analyze quality
    const quality = await analyzeImageBlob(file);
    // gate: if blurry or dark, lock and ask user to retake by default
    let flagged = false;
    if (quality.isBlurry || quality.isDark) {
      // lock progression until user confirms override
      setGateLocked(true);
      setWarning(quality.isBlurry ? "检测到模糊，建议重拍以获得更清晰的图像。" : "图像偏暗，建议重拍。");
      // show UI to either Retake or Force Use
      // we'll wait for user action: Retake will remove result; Force Use will continue but flagged=true
      // To facilitate synchronous UX, we still populate preview but block Next
    } else {
      setGateLocked(false);
      setWarning(null);
    }

    const blobUrl = URL.createObjectURL(file);
    const newResult: CaptureResult = { view: currentView, file, blobUrl, quality, exif: exif ?? null, flagged: false };

    // optionally upload automatically (include metadata/exif field)
    if (autoUpload) {
      try {
        const upload = await uploadFileToApi(file, exif);
        newResult.upload = upload;
      } catch (err) {
        console.warn("upload failed", err);
        newResult.upload = null;
      }
    }

    setResults((prev) => {
      const copy = [...prev];
      copy[index] = newResult;
      return copy;
    });
  }

  async function uploadFileToApi(file: File, exif?: any): Promise<{ url: string; key: string }> {
    const fd = new FormData();
    fd.append("file", file);
    if (exif) fd.append("metadata", JSON.stringify({ exif }));
    const res = await fetch("/api/uploads", { method: "POST", body: fd });
    if (!res.ok) throw new Error(`upload failed: ${res.status}`);
    const json = await res.json();
    return { url: json.url, key: json.key };
  }

  function forceUse() {
    // mark current as forced and allow next
    setResults((prev) => {
      const copy = [...prev];
      if (copy[index]) copy[index] = { ...copy[index], flagged: true };
      return copy;
    });
    setGateLocked(false);
    setWarning(null);
  }

  function retake() {
    setResults((prev) => {
      const copy = [...prev];
      copy[index] = undefined as any;
      return copy;
    });
    setGateLocked(false);
    setWarning(null);
  }

  function goNext() {
    if (gateLocked) {
      alert("当前照片质量不佳，请重拍或强制使用。");
      return;
    }
    if (index < views.length - 1) setIndex(index + 1);
    else {
      onComplete?.(results);
    }
  }

  function goPrev() {
    if (index > 0) setIndex(index - 1);
  }

  const currentResult = results[index];

  return (
    <div style={{ maxWidth: 920, margin: "0 auto", fontFamily: "Arial, sans-serif" }}>
      <h2>拍照定制车贴 — 拍摄引导</h2>
      <p>当前视角：<strong>{currentView}</strong>（{index + 1}/{views.length}）</p>

      <div style={{ display: "flex", gap: 16 }}>
        <div style={{ width: 520, border: "1px solid #ddd", padding: 8, borderRadius: 6 }}>
          <div style={{ position: "relative", width: "100%", paddingTop: "56.25%", background: "#000" }}>
            <video
              ref={videoRef}
              playsInline
              muted
              style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", objectFit: "cover" }}
            />
            <div style={{
              position: "absolute", inset: 12, border: "2px dashed rgba(255,255,255,0.6)",
              display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", textShadow: "0 0 6px rgba(0,0,0,0.8)",
              pointerEvents: "none"
            }}>
              <div style={{ textAlign: "center" }}>
                <div style={{ fontWeight: 700 }}>{currentView.toUpperCase()}</div>
                <div style={{ fontSize: 13 }}>请使车辆完整出现在框内，避免强逆光与明显模糊</div>
              </div>
            </div>

            {currentResult?.blobUrl && (
              <img src={currentResult.blobUrl} alt="preview" style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", objectFit: "cover" }} />
            )}
          </div>

          <div style={{ marginTop: 8, display: "flex", gap: 8, alignItems: "center" }}>
            <button onClick={() => fileInputRef.current?.click()} disabled={busy}>从相册选择</button>
            <input ref={fileInputRef} type="file" accept="image/*" capture="environment" style={{ display: "none" }} onChange={handleFileInput} />
            <button onClick={toggleFacing} disabled={busy} title="切换摄像头">切换摄像头</button>
            <button onClick={handleCaptureFromCamera} disabled={busy || !!currentResult}>拍照</button>
            {currentResult && <button onClick={retake} disabled={busy}>重拍</button>}
            <div style={{ marginLeft: "auto" }}>
              <button onClick={goPrev} disabled={index === 0}>上一步</button>
              <button onClick={() => { if (!currentResult) { alert("请先拍照或选择图片"); return; } goNext(); }} style={{ marginLeft: 8 }}>
                {index < views.length - 1 ? "下一步" : "完成"}
              </button>
            </div>
          </div>

          <div style={{ marginTop: 8 }}>
            {busy && <div>处理中…</div>}
            {warning && <div style={{ color: "#b44" }}>{warning}</div>}
            {gateLocked && (
              <div style={{ marginTop: 8 }}>
                <div>检测到图像质量问题：</div>
                <button onClick={retake} style={{ marginRight: 8 }}>重拍</button>
                <button onClick={forceUse}>仍然使用此图</button>
              </div>
            )}
            {currentResult?.quality && (
              <div style={{ fontSize: 13, color: "#333" }}>
                模糊度: {currentResult.quality.blurScore.toFixed(1)} ({currentResult.quality.isBlurry ? "模糊" : "清晰"}) · 亮度: {currentResult.quality.brightness.toFixed(0)} ({currentResult.quality.isDark ? "偏暗" : "亮度正常"})
              </div>
            )}
            {currentResult?.exif && (
              <div style={{ fontSize: 12, color: "#666", marginTop: 6 }}>
                EXIF: {currentResult.exif.make ?? ""} {currentResult.exif.model ?? ""} {currentResult.exif.latitude ? `· GPS(${currentResult.exif.latitude.toFixed(6)},${currentResult.exif.longitude?.toFixed(6)})` : ""}
              </div>
            )}
            {currentResult?.upload && (
              <div style={{ fontSize: 13, marginTop: 6 }}>
                已上传: <a href={currentResult.upload.url} target="_blank" rel="noreferrer">查看</a>
              </div>
            )}
            {currentResult?.upload === null && (
              <div style={{ color: "#a33", fontSize: 13 }}>上传失败，请稍后重试。</div>
            )}
          </div>
        </div>

        <div style={{ flex: 1 }}>
          <h4>拍摄进度</h4>
          <ul>
            {views.map((v, i) => {
              const r = results[i];
              return (
                <li key={v} style={{ marginBottom: 8 }}>
                  <strong>{v}</strong> — {r ? (r.upload ? "已上传" : "已拍摄") : "未拍摄"}
                  {r?.quality && (
                    <div style={{ fontSize: 12, color: "#555" }}>
                      blur {r.quality.blurScore.toFixed(1)}, bright {Math.round(r.quality.brightness)}
                    </div>
                  )}
                </li>
              );
            })}
          </ul>

          <div style={{ marginTop: 12 }}>
            <strong>提示</strong>
            <ul style={{ fontSize: 13 }}>
              <li>尽量在白天或光线充足的环境拍摄。</li>
              <li>保持相机稳定，避免模糊。</li>
              <li>确保车牌、人像等隐私信息被自动遮挡或可手动编辑（模板编辑阶段）。</li>
            </ul>
          </div>

          <div style={{ marginTop: 12 }}>
            <button onClick={() => { onComplete?.(results); }} style={{ background: "#0b79f7", color: "#fff", padding: "8px 12px", borderRadius: 4 }}>
              跳过并提交当前已拍摄项
            </button>
          </div>
        </div>
      </div>

      <canvas ref={canvasRef} style={{ display: "none" }} />
    </div>
  );
}
