```tsx name=frontend/src/pages/DemoPage.tsx
import React, { useState } from "react";
import CaptureGuide, { CaptureResult } from "../components/CaptureGuide";
import Editor from "../components/Editor";

export default function DemoPage() {
  const [step, setStep] = useState<"capture" | "editor">("capture");
  const [initialImageUrl, setInitialImageUrl] = useState<string | undefined>(undefined);

  async function handleCaptureComplete(results: CaptureResult[]) {
    // choose best available processed URL (prefer processed upload url if exists)
    // Here we pick first successful upload URL
    const uploaded = results.find((r) => r && r.upload && r.upload.url);
    if (uploaded && uploaded.upload) {
      // optionally, you might want to call /api/process to generate processed image and wait
      setInitialImageUrl(uploaded.upload.url);
    } else {
      // fallback to local blob url of first captured
      const first = results.find((r) => r && r.blobUrl);
      setInitialImageUrl(first?.blobUrl);
    }
    setStep("editor");
  }

  return (
    <div>
      {step === "capture" && <CaptureGuide onComplete={handleCaptureComplete} />}
      {step === "editor" && <Editor initialImageUrl={initialImageUrl} onSave={() => alert("已保存模板")} />}
    </div>
  );
}
