import express from "express";
import cors from "cors";
import path from "path";
import fs from "fs";
import http from "http";
import { Server as IOServer } from "socket.io";
import IORedis from "ioredis";
import uploads from "./routes/uploads";
import templates from "./routes/templates";
import masks from "./routes/masks";
import pool, { initDb } from "./db";
import { ensureBucket } from "./s3";

const app = express();
app.use(cors());
// increase body limit for mask uploads
app.use(express.json({ limit: "20mb" }));
app.use(express.urlencoded({ extended: true, limit: "20mb" }));

const PORT = Number(process.env.PORT || 4000);

// ensure data dir exists
const DATA_DIR = path.join(process.cwd(), "data");
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

initDb().then(async () => {
  try {
    await ensureBucket();
    console.log("S3 bucket ensured.");
  } catch (err) {
    console.warn("S3 bucket ensure failed (proceeding):", err);
  }

  app.get("/api/health", (_req, res) => res.json({ status: "ok" }));

  app.use("/api/uploads", uploads);
  app.use("/api/templates", templates);
  app.use("/api/masks", masks);

  // create HTTP server & attach Socket.IO
  const server = http.createServer(app);
  const io = new IOServer(server, {
    cors: { origin: "*" }
  });

  // Redis subscriber to forward job updates to connected clients
  const redisHost = process.env.REDIS_HOST || "localhost";
  const redisPort = Number(process.env.REDIS_PORT || 6379);
  const sub = new IORedis({ host: redisHost, port: redisPort });

  sub.subscribe("job_updates", (err, count) => {
    if (err) console.error("Redis subscribe error:", err);
    else console.log("Subscribed to job_updates, count=", count);
  });

  sub.on("message", (_channel, message) => {
    try {
      const payload = JSON.parse(message);
      const jobId = payload.jobId;
      // Emit globally and into a job-specific room
      io.emit("job_update", payload);
      if (jobId) {
        io.to(`job_${jobId}`).emit("job_update", payload);
      }
    } catch (err) {
      console.warn("Invalid job update payload:", err);
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);
    socket.on("subscribe_job", (jobId: number) => {
      try {
        socket.join(`job_${jobId}`);
      } catch {}
    });
    socket.on("unsubscribe_job", (jobId: number) => {
      try {
        socket.leave(`job_${jobId}`);
      } catch {}
    });
    socket.on("disconnect", () => {
      // cleanup if needed
    });
  });

  server.listen(PORT, () => {
    console.log(`Backend (with socket.io) listening on port ${PORT}`);
  });
}).catch((err) => {
  console.error("DB init error", err);
