6) processor/src/worker.ts — publish Redis job updates after DB update
```ts name=processor/src/worker.ts
import { Worker } from "bullmq";
import IORedis from "ioredis";
import { S3Client, GetObjectCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import sharp from "sharp";
import { Pool } from "pg";

const REDIS_HOST = process.env.REDIS_HOST || "localhost";
const REDIS_PORT = Number(process.env.REDIS_PORT || 6379);

const PGPOOL = new Pool({
  host: process.env.PGHOST || "localhost",
  user: process.env.PGUSER || "postgres",
  password: process.env.PGPASSWORD || "postgres",
  database: process.env.PGDATABASE || "poddb"
});

const S3_ENDPOINT = process.env.S3_ENDPOINT;
const S3_REGION = process.env.S3_REGION || "us-east-1";
const S3_ACCESS = process.env.S3_ACCESS_KEY || "minioadmin";
const S3_SECRET = process.env.S3_SECRET_KEY || "minioadmin";
const S3_BUCKET = process.env.S3_BUCKET || "pod";

const s3 = new S3Client({
  region: S3_REGION,
  endpoint: S3_ENDPOINT,
  credentials: { accessKeyId: S3_ACCESS, secretAccessKey: S3_SECRET },
  forcePathStyle: true
});

function streamToBufferAsync(body: any): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    if (!body || typeof body.on !== "function") {
      return reject(new Error("Invalid body stream"));
    }
    body.on("data", (chunk: Buffer) => chunks.push(chunk));
    body.on("end", () => resolve(Buffer.concat(chunks)));
    body.on("error", (err: any) => reject(err));
  });
}

const redisPub = new IORedis({ host: REDIS_HOST, port: REDIS_PORT });

async function publishJobUpdate(jobId: number, status: string, result: any) {
  try {
    await redisPub.publish("job_updates", JSON.stringify({ jobId, status, result }));
  } catch (err) {
    console.warn("publishJobUpdate error:", err);
  }
}

async function processJob(job: any) {
  const payload = job.data.payload;
  const key = payload.key;
  try {
    console.log("Processing job for key:", key);
    const get = await s3.send(new GetObjectCommand({ Bucket: S3_BUCKET, Key: key }));
    const body = get.Body as any;
    const buffer = await streamToBufferAsync(body);

    const resized = sharp(buffer).resize(1200, { fit: "inside" });
    const meta = await resized.metadata();
    const width = meta.width || 1200;
    const height = meta.height || 800;

    const svg = `
      <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
        <style>
          .t { fill: white; font-size: ${Math.round(Math.max(14, width / 30))}px; font-family: Arial, sans-serif;
               stroke: black; stroke-width: 2px; paint-order: stroke; }
        </style>
        <text x="${width - 20}" y="${height - 20}" text-anchor="end" class="t">Processed</text>
      </svg>
    `;
    const processedBuffer = await resized
      .composite([{ input: Buffer.from(svg), gravity: "southeast" }])
      .jpeg({ quality: 85 })
      .toBuffer();

    const outKey = key.replace("uploads/", "processed/");
    await s3.send(new PutObjectCommand({ Bucket: S3_BUCKET, Key: outKey, Body: processedBuffer, ContentType: "image/jpeg" }));

    // update DB job
    // job.data.jobId was set when enqueuing
    await PGPOOL.query("UPDATE jobs SET status=$1, result=$2, updated_at=now() WHERE id=$3", ["done", { key: outKey }, job.data.jobId]);

    // publish update for real-time notification
    await publishJobUpdate(job.data.jobId, "done", { key: outKey, url: `${S3_ENDPOINT?.replace(/\/+$/, "")}/${S3_BUCKET}/${outKey}` });

    console.log("Job done, outKey:", outKey);
  } catch (err) {
    console.error("processJob error:", err && (err as any).stack ? (err as any).stack : err);
    try {
      await PGPOOL.query("UPDATE jobs SET status=$1, result=$2, updated_at=now() WHERE id=$3", ["failed", { error: String(err) }, job.data.jobId]);
      await publishJobUpdate(job.data.jobId, "failed", { error: String(err) });
    } catch (e) {
      console.error("Failed to update job status in DB:", e);
    }
  }
}

const connection = new IORedis({ host: REDIS_HOST, port: REDIS_PORT });
const worker = new Worker("image-processing", async (job) => {
  await processJob(job);
}, { connection });

worker.on("completed", (job) => {
  console.log(`Worker completed job ${job.id}`);
});
worker.on("failed", (job, err) => {
  console.error(`Worker failed job ${job?.id}:`, err);
});

console.log("Processor worker started, listening to queue image-processing");
```

