  app.use("/api/uploads", uploads);
  app.use("/api/templates", templates);
  app.use("/api/masks", masks);
  app.use("/api/measurements", measurements);

  // HTTP + Socket.IO (Redis pub/sub forwarding)
  const server = http.createServer(app);
  const io = new IOServer(server, { cors: { origin: "*" } });

  const redisHost = process.env.REDIS_HOST || "localhost";
  const redisPort = Number(process.env.REDIS_PORT || 6379);
  const sub = new IORedis({ host: redisHost, port: redisPort });

  sub.subscribe("job_updates", (err, count) => {
    if (err) console.error("Redis subscribe error:", err);
    else console.log("Subscribed to job_updates, count=", count);
  });

  sub.on("message", (_channel, message) => {
    try {
      const payload = JSON.parse(message);
      const jobId = payload.jobId;
      io.emit("job_update", payload);
      if (jobId) io.to(`job_${jobId}`).emit("job_update", payload);
    } catch (err) {
      console.warn("Invalid job update payload:", err);
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);
    socket.on("subscribe_job", (jobId: number) => {
      try { socket.join(`job_${jobId}`); } catch {}
    });
    socket.on("unsubscribe_job", (jobId: number) => {
      try { socket.leave(`job_${jobId}`); } catch {}
    });
  });

  server.listen(PORT, () => {
    console.log(`Backend (with socket.io) listening on port ${PORT}`);
  });
}).catch((err) => {
  console.error("DB init error", err);
  process.exit(1);
});
