```tsx name=frontend/src/components/CalibrationTool.tsx
import React, { useEffect, useRef, useState } from "react";

type Point = { x: number; y: number };

type Props = {
  imageSrc: string; // image to calibrate (URL or blob URL)
  onUpdate?: (scaleMetersPerPixel: number | null, p1?: Point, p2?: Point) => void;
  initialDistanceMeters?: number | null; // optional known distance between two clicked points
  canvasWidth?: number;
  canvasHeight?: number;
};

/**
 * CalibrationTool:
 * - shows image in a canvas (fitting into canvasWidth x canvasHeight)
 * - user clicks two points (or drags) to select calibration segment
 * - user inputs real-world distance between the two points (meters/selected unit)
 * - outputs scale = metersPerPixel
 */
export default function CalibrationTool({
  imageSrc,
  onUpdate,
  initialDistanceMeters = null,
  canvasWidth = 900,
  canvasHeight = 600
}: Props) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [img, setImg] = useState<HTMLImageElement | null>(null);
  const [imgNatural, setImgNatural] = useState<{ w: number; h: number } | null>(null);
  const [points, setPoints] = useState<Point[]>([]);
  const [realDistance, setRealDistance] = useState<number | null>(initialDistanceMeters);
  const [unit, setUnit] = useState<"m" | "cm" | "mm">("m");
  const [scaleMPerPx, setScaleMPerPx] = useState<number | null>(null);

  // load image
  useEffect(() => {
    if (!imageSrc) {
      setImg(null);
      setImgNatural(null);
      return;
    }
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => {
      setImg(image);
      setImgNatural({ w: image.naturalWidth, h: image.naturalHeight });
      draw(image, points);
    };
    image.onerror = () => {
      setImg(null);
      setImgNatural(null);
    };
    image.src = imageSrc;
    return () => {
      // cleanup
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [imageSrc]);

  useEffect(() => {
    if (img) draw(img, points);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [points, img, canvasWidth, canvasHeight]);

  function getCanvas() {
    let c = canvasRef.current;
    if (!c) {
      c = document.createElement("canvas");
      canvasRef.current = c;
    }
    return c;
  }

  function fitImageRect(imgW: number, imgH: number) {
    const maxW = canvasWidth;
    const maxH = canvasHeight;
    const scale = Math.min(maxW / imgW, maxH / imgH, 1);
    const w = Math.round(imgW * scale);
    const h = Math.round(imgH * scale);
    const offsetX = Math.round((maxW - w) / 2);
    const offsetY = Math.round((maxH - h) / 2);
    return { w, h, offsetX, offsetY, scale };
  }

  function draw(image: HTMLImageElement, pts: Point[]) {
    const canvas = getCanvas();
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
    const ctx = canvas.getContext("2d")!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (!image) return;
    const r = fitImageRect(image.naturalWidth, image.naturalHeight);
    ctx.fillStyle = "#222";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(image, 0, 0, image.naturalWidth, image.naturalHeight, r.offsetX, r.offsetY, r.w, r.h);

    // draw overlay guides
    ctx.strokeStyle = "rgba(255,255,255,0.6)";
    ctx.lineWidth = 1;
    ctx.strokeRect(r.offsetX + 0.5, r.offsetY + 0.5, r.w - 1, r.h - 1);

    // draw points & segment
    if (pts.length > 0) {
      ctx.fillStyle = "rgba(255,0,0,0.9)";
      pts.forEach((p, i) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#fff";
        ctx.font = "12px Arial";
        ctx.fillText(String(i + 1), p.x + 8, p.y - 8);
        ctx.fillStyle = "rgba(255,0,0,0.9)";
      });
    }
    if (pts.length === 2) {
      ctx.strokeStyle = "lime";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      ctx.lineTo(pts[1].x, pts[1].y);
      ctx.stroke();

      const pxLen = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y);
      ctx.fillStyle = "#fff";
      ctx.font = "14px Arial";
      ctx.fillText(`${pxLen.toFixed(1)} px`, (pts[0].x + pts[1].x) / 2 + 8, (pts[0].y + pts[1].y) / 2 - 8);
    }
  }

  function clientToImageCoords(clientX: number, clientY: number): Point | null {
    const container = containerRef.current;
    const imageEl = img;
    if (!container || !imageEl || !imgNatural) return null;
    const rect = container.getBoundingClientRect();
    const localX = clientX - rect.left;
    const localY = clientY - rect.top;
    // map local to fitted image region
    const r = fitImageRect(imgNatural.w, imgNatural.h);
    // if outside image area, ignore
    if (localX < r.offsetX || localX > r.offsetX + r.w || localY < r.offsetY || localY > r.offsetY + r.h) return null;
    return { x: localX, y: localY };
  }

  function handleCanvasClick(e: React.MouseEvent) {
    const pt = clientToImageCoords(e.clientX, e.clientY);
    if (!pt) return;
    setPoints((prev) => {
      const next = [...prev];
      if (next.length >= 2) next.splice(0, next.length); // reset
      next.push(pt);
      return next;
    });
  }

  useEffect(() => {
    // whenever points or realDistance updated, compute scale
    if (points.length === 2 && realDistance && imgNatural) {
      const pxLen = Math.hypot(points[1].x - points[0].x, points[1].y - points[0].y);
      // pxLen is in canvas pixel coordinates. We need meters per pixel as realDistance / pxLen.
      const meters = convertToMeters(realDistance, unit);
      const mPerPx = meters / pxLen;
      setScaleMPerPx(mPerPx);
      onUpdate?.(mPerPx, points[0], points[1]);
    } else {
      setScaleMPerPx(null);
      onUpdate?.(null, points[0], points[1]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [points, realDistance, unit, imgNatural]);

  function convertToMeters(v: number, u: "m" | "cm" | "mm") {
    if (u === "m") return v;
    if (u === "cm") return v / 100;
    return v / 1000;
  }

  return (
    <div>
      <div ref={containerRef} style={{ width: canvasWidth, height: canvasHeight, border: "1px solid #ccc", position: "relative" }}>
        <canvas ref={canvasRef} width={canvasWidth} height={canvasHeight} onClick={handleCanvasClick} />
        {/* overlay the drawn canvas from draw() by painting onto ref canvas */}
      </div>

      <div style={{ marginTop: 8, display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
        <div>
          <label>
            真实距离:
            <input
              type="number"
              value={realDistance ?? ""}
              onChange={(e) => setRealDistance(e.target.value ? Number(e.target.value) : null)}
              style={{ marginLeft: 6, width: 110 }}
            />
          </label>
        </div>
        <div>
          <label>
            单位:
            <select value={unit} onChange={(e) => setUnit(e.target.value as any)} style={{ marginLeft: 6 }}>
              <option value="m">m</option>
              <option value="cm">cm</option>
              <option value="mm">mm</option>
            </select>
          </label>
        </div>

        <div style={{ marginLeft: "auto" }}>
          <button
            onClick={() => {
              setPoints([]);
              setRealDistance(null);
              setScaleMPerPx(null);
            }}
          >
            重置
          </button>
        </div>
      </div>

      <div style={{ marginTop: 8 }}>
        <small style={{ color: "#666" }}>
          使用方法：1) 在图上点击两个点（例如车左右外缘或门把手两端）；2) 在“真实距离”中输入这两个点之间的实际距离（来自行驶证或人工测量）；3) 系统将计算出米/像素尺度（m/px）。
        </small>
      </div>

      <div style={{ marginTop: 8 }}>
        <strong>当前 scale:</strong> {scaleMPerPx ? `${scaleMPerPx.toExponential(6)} m/px (${(1 / scaleMPerPx).toFixed(2)} px/m)` : "尚未计算"}
      </div>
    </div>
  );
}
