export function pxToMeters(px: number, metersPerPixel: number) {
  return px * metersPerPixel;
}
export function metersToPx(meters: number, metersPerPixel: number) {
  return meters / metersPerPixel;
}

// convert unit value to meters
export function toMeters(value: number, unit: "m" | "cm" | "mm") {
  if (unit === "m") return value;
  if (unit === "cm") return value / 100;
  return value / 1000;
}
