```tsx name=frontend/src/pages/MeasurementImportPage.tsx
import React, { useState } from "react";
import CaptureGuide, { CaptureResult } from "../components/CaptureGuide";
import VehicleInfoForm, { VehicleDimensions } from "../components/VehicleInfoForm";
import CalibrationTool from "../components/CalibrationTool";
import Editor from "../components/Editor";
import { pxToMeters } from "../utils/scale";

/**
 * MeasurementImportPage:
 * - Step 1: capture images (use existing CaptureGuide) -> get at least one image upload URL or blobUrl
 * - Step 2: user inputs vehicle dimensions (or selects model)
 * - Step 3: user calibrates two points on the image to compute metersPerPixel (scale)
 * - Step 4: (demo) convert an example polygon (or parts returned from backend) from px to meters and import to Editor.
 *
 * This page is a front-end integration demo. In a real app you'd send the uploaded image key + dims to backend /api/measurements
 * and receive parts with polygons + rectified images & physical sizes. Here we demonstrate the local calibration -> conversion flow.
 */

export default function MeasurementImportPage() {
  const [step, setStep] = useState<"capture" | "measure" | "calibrate" | "editor">("capture");
  const [captureResults, setCaptureResults] = useState<CaptureResult[]>([]);
  const [vehicleDims, setVehicleDims] = useState<VehicleDimensions | null>(null);
  const [scaleMPerPx, setScaleMPerPx] = useState<number | null>(null);
  const [selectedImageUrl, setSelectedImageUrl] = useState<string | null>(null);
  const [importAreas, setImportAreas] = useState<any[]>([]); // example parts

  async function handleCaptureComplete(results: CaptureResult[]) {
    setCaptureResults(results);
    // pick first uploaded (processed) url or blob
    const u = results.find((r) => r && r.upload && r.upload.url);
    const b = results.find((r) => r && r.blobUrl);
    setSelectedImageUrl(u?.upload?.url ?? b?.blobUrl ?? null);
    setStep("measure");
  }

  function handleVehicleChange(dims: VehicleDimensions) {
    setVehicleDims(dims);
  }

  function handleScaleUpdate(scale: number | null) {
    setScaleMPerPx(scale);
  }

  function demoComputePartsFromMask() {
    // In a real scenario, parts would come from backend measurement pipeline.
    // Here we'll create an example polygon in pixel space and convert to meters.
    if (!selectedImageUrl || !scaleMPerPx) {
      alert("请先选择图片并完成校准（两点标定）。");
      return;
    }
    // Example polygon (px coords relative to canvas used in CalibrationTool)
    const examplePolygonPx = [
      { x: 200, y: 180 },
      { x: 700, y: 180 },
      { x: 700, y: 400 },
      { x: 200, y: 400 }
    ];
    // convert bbox width/height to meters
    const xs = examplePolygonPx.map((p) => p.x);
    const ys = examplePolygonPx.map((p) => p.y);
    const widthPx = Math.max(...xs) - Math.min(...xs);
    const heightPx = Math.max(...ys) - Math.min(...ys);
    const widthM = scaleMPerPx ? pxToMeters(widthPx, scaleMPerPx) : null;
    const heightM = scaleMPerPx ? pxToMeters(heightPx, scaleMPerPx) : null;

    const part = {
      name: "demo_area",
      polygonPx: examplePolygonPx,
      rectifiedUrl: selectedImageUrl,
      rectifiedPx: { w: widthPx, h: heightPx },
      physicalSize: { width_m: widthM, height_m: heightM }
    };
    setImportAreas([part]);
    setStep("editor");
  }

  return (
    <div style={{ padding: 20 }}>
      <h1>车辆测量与导入示例</h1>

      {step === "capture" && <CaptureGuide onComplete={handleCaptureComplete} />}

      {step === "measure" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 480px", gap: 16 }}>
          <div>
            <h3>选择图片并输入车辆参数</h3>
            <div style={{ marginBottom: 12 }}>
              <label>
                选择图片:
                <select
                  onChange={(e) => {
                    const idx = Number(e.target.value);
                    const r = captureResults[idx];
                    setSelectedImageUrl(r?.upload?.url ?? r?.blobUrl ?? null);
                  }}
                  defaultValue={captureResults.findIndex((r) => r.upload?.url || r.blobUrl)}
                >
                  {captureResults.map((r, i) => (
                    <option key={i} value={i}>
                      {r.view} — {r.upload?.url ? "processed" : r.blobUrl ? "local" : "none"}
                    </option>
                  ))}
                </select>
              </label>
            </div>

            <VehicleInfoForm onChange={handleVehicleChange} />

            <div style={{ marginTop: 12 }}>
              <button onClick={() => setStep("calibrate")} disabled={!selectedImageUrl}>
                进入两点校准
              </button>
            </div>
          </div>

          <div>
            <h3>当前选择</h3>
            <div style={{ border: "1px solid #eee", padding: 8 }}>
              <div>图片: {selectedImageUrl ? <a href={selectedImageUrl} target="_blank" rel="noreferrer">打开</a> : "未选择"}</div>
              <div>车辆尺寸: {vehicleDims ? `${vehicleDims.length ?? "-"} ${vehicleDims.unit} × ${vehicleDims.width ?? "-"} × ${vehicleDims.height ?? "-"}` : "未填写"}</div>
              <div style={{ marginTop: 8 }}>
                <small>下一步：校准 -> 生成可设计区域 -> 导入设计器</small>
              </div>
            </div>
          </div>
        </div>
      )}

      {step === "calibrate" && selectedImageUrl && (
        <div>
          <h3>两点校准</h3>
          <CalibrationTool
            imageSrc={selectedImageUrl}
            onUpdate={(scale, p1, p2) => {
              handleScaleUpdate(scale);
            }}
            canvasWidth={1000}
            canvasHeight={640}
          />
          <div style={{ marginTop: 12 }}>
            <button onClick={() => setStep("measure")}>返回</button>
            <button onClick={demoComputePartsFromMask} style={{ marginLeft: 8, background: "#0b79f7", color: "#fff" }}>
              将示例区域按校准导入设计器（演示）
            </button>
          </div>
        </div>
      )}

      {step === "editor" && (
        <div>
          <h3>导入到设计器</h3>
          <div style={{ marginBottom: 8 }}>
            <div>已生成区域数量: {importAreas.length}</div>
            <div>
              {importAreas.map((a, idx) => (
                <div key={idx} style={{ marginTop: 8, padding: 8, border: "1px solid #eee" }}>
                  <div><strong>{a.name}</strong></div>
                  <div>物理尺寸: {a.physicalSize.width_m?.toFixed(3)} m × {a.physicalSize.height_m?.toFixed(3)} m</div>
                </div>
              ))}
            </div>
          </div>

          <Editor initialImageUrl={importAreas[0]?.rectifiedUrl} onSave={() => alert("模板保存（演示）")} />
          <div style={{ marginTop: 12 }}>
            <button onClick={() => { setStep("capture"); setImportAreas([]); }}>重新开始</button>
          </div>
        </div>
      )}
    </div>
  );
}
