```ts name=backend/src/routes/measurements.ts
import express from "express";
import { getObjectStream } from "../s3";
import sizeOf from "image-size";

const router = express.Router();

/**
 * POST /api/measurements
 * Body JSON:
 * {
 *   imageKey: "uploads/xxx.jpg",
 *   vehicle?: { length?: number, width?: number, height?: number, unit?: "m"|"cm"|"mm" },
 *   calibration?: { metersPerPixel?: number }, // optional
 *   options?: { /* future options */ }
 * }
 *
 * Response (demo):
 * {
 *   jobId: null,
 *   status: "done",
 *   result: {
 *     imageKey,
 *     scale_m_per_px,
 *     parts: [
 *       { name, polygon: [{x,y},...], rectifiedUrl, rectifiedPx:{w,h}, physicalSize:{width_m,height_m,area_m2}, confidence }
 *     ]
 *   }
 * }
 */
router.post("/", express.json(), async (req, res) => {
  try {
    const { imageKey, vehicle, calibration } = req.body;
    if (!imageKey) return res.status(400).json({ error: "missing imageKey" });

    // read image bytes from S3/minio
    const stream = await getObjectStream(imageKey);
    // collect into buffer
    const chunks: Buffer[] = [];
    await new Promise<void>((resolve, reject) => {
      stream.on("data", (c: Buffer) => chunks.push(c));
      stream.on("end", () => resolve());
      stream.on("error", (err: any) => reject(err));
    });
    const buf = Buffer.concat(chunks);

    // get image dimensions
    const dims = sizeOf(buf);
    const imgW = dims.width || 0;
    const imgH = dims.height || 0;

    // determine scale (meters per pixel)
    let mPerPx: number | null = null;
    if (calibration && typeof calibration.metersPerPixel === "number") {
      mPerPx = calibration.metersPerPixel;
    } else if (vehicle && typeof vehicle.width === "number") {
      // convert vehicle.width to meters
      let widthMeters = Number(vehicle.width);
      const unit = (vehicle.unit || "m") as "m" | "cm" | "mm";
      if (unit === "cm") widthMeters = widthMeters / 100;
      if (unit === "mm") widthMeters = widthMeters / 1000;
      // estimate pixel vehicle width in image (demo heuristic: 80% of image width)
      const pxVehicleWidth = Math.max(10, Math.round(imgW * 0.8));
      mPerPx = widthMeters / pxVehicleWidth;
    } else {
      // no calibration -> cannot compute physical sizes; return scale null but still parts in px
      mPerPx = null;
    }

    // demo: generate a central rectangular part polygon (as an example "designable area")
    const left = Math.round(imgW * 0.1);
    const right = Math.round(imgW * 0.9);
    const top = Math.round(imgH * 0.3);
    const bottom = Math.round(imgH * 0.7);

    const polygon = [
      { x: left, y: top },
      { x: right, y: top },
      { x: right, y: bottom },
      { x: left, y: bottom }
    ];
    const rectWpx = right - left;
    const rectHpx = bottom - top;

    const physical = mPerPx
      ? {
          width_m: rectWpx * mPerPx,
          height_m: rectHpx * mPerPx,
          area_m2: rectWpx * rectHpx * (mPerPx * mPerPx)
        }
      : { width_m: null, height_m: null, area_m2: null };

    // Build rectifiedUrl (for demo we point to the original object URL)
    const endpoint = process.env.S3_ENDPOINT ? process.env.S3_ENDPOINT.replace(/\/+$/, "") : "";
    const bucket = process.env.S3_BUCKET || "pod";
    const rectifiedUrl = endpoint ? `${endpoint}/${bucket}/${imageKey}` : `${bucket}/${imageKey}`;

    const part = {
      name: "demo_center_area",
      polygon,
      rectifiedUrl,
      rectifiedPx: { w: rectWpx, h: rectHpx },
      physicalSize: physical,
      confidence: 0.6
    };

    return res.json({
      jobId: null,
      status: "done",
      result: {
        imageKey,
        imagePx: { width: imgW, height: imgH },
        scale_m_per_px: mPerPx,
        parts: [part]
      }
    });
  } catch (err: any) {
    console.error("measurements error", err);
    return res.status(500).json({ error: "measurement failed", details: String(err) });
  }
});

export default router;
```

```ts name=backend/src/index.ts
import express from "express";
import cors from "cors";
import path from "path";
import fs from "fs";
import http from "http";
import { Server as IOServer } from "socket.io";
import IORedis from "ioredis";
import uploads from "./routes/uploads";
import templates from "./routes/templates";
import masks from "./routes/masks";
import measurements from "./routes/measurements";
import pool, { initDb } from "./db";
import { ensureBucket } from "./s3";

const app = express();
app.use(cors());
// increase body limit for mask uploads / measurement requests
app.use(express.json({ limit: "30mb" }));
app.use(express.urlencoded({ extended: true, limit: "30mb" }));

const PORT = Number(process.env.PORT || 4000);

// ensure data dir exists
const DATA_DIR = path.join(process.cwd(), "data");
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

initDb().then(async () => {
  try {
    await ensureBucket();
    console.log("S3 bucket ensured.");
  } catch (err) {
    console.warn("S3 bucket ensure failed (proceeding):", err);
  }

  app.get("/api/health", (_req, res) => res.json({ status: "ok" }));

  app.use("/api/uploads", uploads);
  app.use("/api/templates", templates);
  app.use("/api/masks", masks);
  app.use("/api/measurements", measurements);

  // create HTTP server & attach Socket.IO
  const server = http.createServer(app);
  const io = new IOServer(server, {
    cors: { origin: "*" }
  });

  const redisHost = process.env.REDIS_HOST || "localhost";
  const redisPort = Number(process.env.REDIS_PORT || 6379);
  const sub = new IORedis({ host: redisHost, port: redisPort });

  sub.subscribe("job_updates", (err, count) => {
    if (err) console.error("Redis subscribe error:", err);
    else console.log("Subscribed to job_updates, count=", count);
  });

  sub.on("message", (_channel, message) => {
    try {
      const payload = JSON.parse(message);
      const jobId = payload.jobId;
      io.emit("job_update", payload);
      if (jobId) {
        io.to(`job_${jobId}`).emit("job_update", payload);
      }
    } catch (err) {
      console.warn("Invalid job update payload:", err);
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);
    socket.on("subscribe_job", (jobId: number) => {
      try {
        socket.join(`job_${jobId}`);
      } catch {}
    });
    socket.on("unsubscribe_job", (jobId: number) => {
      try {
        socket.leave(`job_${jobId}`);
      } catch {}
    });
  });

  server.listen(PORT, () => {
    console.log(`Backend (with socket.io) listening on port ${PORT}`);
  });
}).catch((err) => {
  console.error("DB init error", err);
  process.exit(1);
});
