import React, { useState } from "react";
import MeasurementImporter, { MeasurementResult } from "../components/MeasurementImporter";
import MeasuredEditor from "../components/MeasuredEditor";
import CaptureGuide from "../components/CaptureGuide";

/**
 * DemoPage flow:
 * 1) CaptureGuide => upload image(s) => choose imageKey (first uploaded) and trigger measurement
 * 2) MeasurementImporter posts measurement job and waits result
 * 3) When done, open MeasuredEditor with first part
 */

export default function DemoPage() {
  const [step, setStep] = useState<"capture"|"measure"|"editor">("capture");
  const [selectedImageKey, setSelectedImageKey] = useState<string | null>(null);
  const [measurement, setMeasurement] = useState<MeasurementResult | null>(null);

  return (
    <div style={{ padding: 16 }}>
      {step === "capture" && (
        <div>
          <CaptureGuide
            onComplete={(results: any[]) => {
              // pick first uploaded item's key if available
              const uploaded = results.find((r) => r && r.upload && r.upload.key);
              const key = uploaded?.upload?.key;
              if (key) {
                setSelectedImageKey(key);
                setStep("measure");
              } else {
                alert("未检测到已上传的图片，请先上传");
              }
            }}
          />
        </div>
      )}

      {step === "measure" && selectedImageKey && (
        <div>
          <button onClick={() => setStep("capture")}>返回拍摄</button>
          <div style={{ marginTop: 12 }}>
            <MeasurementImporter
              imageKey={selectedImageKey}
              vehicle={{ W: 1800, unit: "mm" }} // example: can prompt user to enter real dims
              onDone={(res) => {
                setMeasurement(res);
                setStep("editor");
              }}
            />
          </div>
        </div>
      )}

      {step === "editor" && measurement && measurement.parts && measurement.parts.length > 0 && (
        <div>
          <button onClick={() => setStep("measure")}>返回测量</button>
          <div style={{ marginTop: 12 }}>
            <MeasuredEditor part={measurement.parts[0]} onSaveTemplate={(payload) => {
              // optionally send to /api/templates
              fetch("/api/templates", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) })
                .then((r) => r.json())
                .then((j) => alert("Saved template id: " + j.id))
                .catch((e) => alert("保存失败: " + e));
            }} />
          </div>
        </div>
      )}
    </div>
  );
}
```

使用与测试说明（简短）

1. 安装依赖（若尚未）：
   - npm install react-konva konva socket.io-client

2. 启动前端：
