import React, { useEffect, useMemo, useRef, useState } from "react";
import { Stage, Layer, Image as KImage, Rect } from "react-konva";

type MeasurementPart = {
  name: string;
  rectifiedUrl?: string;
  rectifiedPx?: { w: number; h: number };
  physicalSize?: { width_m: number; height_m: number; area_m2: number };
  maskUrl?: string;
};

type Props = {
  part: MeasurementPart;
  dpi?: number; // e.g., 300
  maxCanvasPx?: number; // cap to avoid huge canvases
  onSaveTemplate?: (payload: any) => void;
};

function useImage(url?: string) {
  const [img, setImg] = useState<HTMLImageElement | null>(null);
  useEffect(() => {
    if (!url) { setImg(null); return; }
    const i = new Image();
    i.crossOrigin = "anonymous";
    i.onload = () => setImg(i);
    i.src = url;
    return () => { setImg(null); };
  }, [url]);
  return img;
}

export default function MeasuredEditor({ part, dpi = 300, maxCanvasPx = 1600, onSaveTemplate }: Props) {
  // physical size in meters
  const widthM = part.physicalSize?.width_m ?? 0.0;
  const heightM = part.physicalSize?.height_m ?? 0.0;

  // convert to mm
  const widthMM = widthM * 1000;
  const heightMM = heightM * 1000;

  // px per mm at given DPI
  const pxPerMMAtDpi = dpi / 25.4; // 1 inch = 25.4 mm
  // desired pixel size
  const desiredPxW = Math.max(1, Math.round(widthMM * pxPerMMAtDpi));
  const desiredPxH = Math.max(1, Math.round(heightMM * pxPerMMAtDpi));

  // scale factor to cap maximum pixel dimensions for UI responsiveness
  const scaleFactor = Math.min(1, maxCanvasPx / Math.max(desiredPxW, desiredPxH, 1));

  // effective canvas pixel dimensions
  const canvasW = Math.max(1, Math.round(desiredPxW * scaleFactor));
  const canvasH = Math.max(1, Math.round(desiredPxH * scaleFactor));

  const img = useImage(part.rectifiedUrl);
  const maskImg = useImage(part.maskUrl);

  const stageRef = useRef<any>(null);

  // mapping info to preserve real-scale info for export
  const mapping = useMemo(() => ({
    dpi,
    pxPerMM: pxPerMMAtDpi * scaleFactor,
    scaleFactor,
    desiredPxW,
    desiredPxH,
    canvasW,
    canvasH
  }), [dpi, pxPerMMAtDpi, scaleFactor, desiredPxW, desiredPxH, canvasW, canvasH]);

  useEffect(() => {
    // optional: fit stage in container, etc.
  }, [canvasW, canvasH]);

  async function exportTemplate() {
    // capture design as image or assemble template payload
    // For now we create a simple payload with image URL + mask + mapping metadata
    const payload = {
      name: `measured-${part.name}`,
      design: {}, // placeholder for Konva JSON if extended
      assets: [part.rectifiedUrl, part.maskUrl].filter(Boolean),
      measurement: {
        width_m: part.physicalSize?.width_m,
        height_m: part.physicalSize?.height_m,
        mapping
      }
    };
    if (onSaveTemplate) onSaveTemplate(payload);
    else {
      // fallback: POST to /api/templates
      try {
        const res = await fetch("/api/templates", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload)
        });
        if (!res.ok) throw new Error(await res.text());
        const js = await res.json();
        alert("模板已保存，id=" + js.id);
      } catch (err: any) {
        alert("保存模板失败: " + (err.message || err));
      }
    }
  }

  return (
    <div style={{ padding: 12 }}>
      <h3>物理尺寸画布 — {part.name}</h3>
      <div style={{ marginBottom: 8 }}>
        <strong>尺寸：</strong>
        {widthM ? `${(widthM*100).toFixed(1)} cm` : "未知"} × {heightM ? `${(heightM*100).toFixed(1)} cm` : "未知"}
        <span style={{ marginLeft: 12 }}>DPI: {dpi} · UI scale: {scaleFactor.toFixed(3)} · px/mm: {(mapping.pxPerMM).toFixed(3)}</span>
      </div>

      <div style={{ border: "1px solid #ccc", width: canvasW, height: canvasH }}>
        <Stage width={canvasW} height={canvasH} ref={stageRef} scaleX={1} scaleY={1}>
          <Layer>
            {img && <KImage image={img} x={0} y={0} width={canvasW} height={canvasH} />}
            {/* mask overlay if exists */}
            {maskImg && <KImage image={maskImg} x={0} y={0} width={canvasW} height={canvasH} opacity={0.5} />}
            {/* optional visual frame */}
            <Rect x={0} y={0} width={canvasW} height={canvasH} stroke="rgba(0,0,0,0.2)" />
          </Layer>
        </Stage>
      </div>

      <div style={{ marginTop: 10 }}>
        <button onClick={exportTemplate} style={{ background: "#0b79f7", color: "#fff", padding: "8px 12px", borderRadius: 4 }}>
          导出为模板 / 保存
        </button>
      </div>
    </div>
  );
}

